    const word = r.complete ? (x.stage === 'discharged' ? 'Discharged' : 'Ready') : tone === 'bad' ? 'Needs a person' : x.items.some((i) => i.state === 'proposed') ? 'Awaiting approval' : x.items.length ? 'In progress' : 'Checking'
